<?php
function page_shipments(array $u):void {
 $manager=is_manager($u);$driver=$u['role']==='driver';
 $query="SELECT sh.*,o.order_code,o.status order_status,o.shipping_address,o.city,o.total,b.company_name,us.name driver_name,us.email driver_email, (SELECT CONCAT(c.name, ' — ', c.address, ', ', c.city) FROM order_items i JOIN products p ON p.id=i.product_id JOIN cooperatives c ON c.id=p.coop_id WHERE i.order_id=o.id LIMIT 1) pickup_address FROM shipments sh JOIN orders o ON o.id=sh.order_id JOIN buyer_profiles b ON b.id=o.buyer_id JOIN users us ON us.id=sh.driver_id";
 if($driver)$ships=rows($query.' WHERE sh.driver_id=? ORDER BY sh.id DESC',[$u['id']]);
 elseif($u['role']==='coop')$ships=rows($query.' WHERE EXISTS(SELECT 1 FROM order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=o.id AND p.coop_id=?) ORDER BY sh.id DESC',[$u['coop_id']]);
 elseif($u['role']==='buyer')$ships=rows($query.' WHERE o.buyer_id=? ORDER BY sh.id DESC',[$u['buyer_id']]);
 else $ships=rows($query.' ORDER BY sh.id DESC');
 $assignable=$manager?rows("SELECT id,order_code FROM orders WHERE status='approved' ORDER BY id DESC"):[];
 $drivers=$manager?rows("SELECT id,name FROM users WHERE role='driver' AND is_active=1 ORDER BY name"):[];
 $events=$ships?rows('SELECT ev.*,u.name actor_name FROM shipment_events ev JOIN users u ON u.id=ev.actor_id ORDER BY ev.id DESC LIMIT 300'):[];
 $by=[];foreach($events as $ev)$by[$ev['shipment_id']][]=$ev;
 if($manager):?><div class="panel panel-pad mb-4 form-card"><h5>Tugaskan driver ke pesanan</h5><p class="helper">Driver hanya dapat ditugaskan setelah persetujuan dan reservasi stok.</p><form class="row g-3" method="post"><?=csrf_input()?><input type="hidden" name="action" value="assign_driver"><div class="col-md-5"><?php select_field('Pesanan siap kirim','id',array_column($assignable,'order_code','id'));?></div><div class="col-md-5"><?php select_field('Driver aktif','driver_id',array_column($drivers,'name','id'));?></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-coco w-100">Assign</button></div></form></div><?php endif;?>
<div class="row g-3"><?php foreach($ships as $s):?><div class="col-xl-6"><div class="panel panel-pad h-100"><div class="d-flex flex-wrap justify-content-between gap-2"><div><div class="helper">PENGIRIMAN #<?=e($s['id'])?></div><h5 class="mt-1 mb-1"><?=e($s['order_code'])?></h5><div class="helper"><?=e($s['company_name'])?> → <?=e($s['city'])?></div></div><div><?=badge($s['status'])?></div></div><hr><div class="row g-2 mb-3"><div class="col-6"><div class="helper">Driver</div><strong><?=e($s['driver_name'])?></strong></div><div class="col-6"><div class="helper">Tujuan</div><strong><?=e($s['shipping_address'])?></strong></div><div class="col-12"><div class="helper">Alamat pickup koperasi</div><strong><?=e($s['pickup_address']??'Belum tersedia')?></strong></div></div>
<?php if($driver&&!in_array($s['status'],['delivered','pickup_pending'],true)): $next=match($s['status']){'assigned'=>'accepted','accepted'=>'pickup_requested','picked_up'=>'delivered',default=>''}; ?><form method="post" enctype="multipart/form-data" class="p-3 mb-3" style="background:#f5f9f4;border-radius:12px"><?=csrf_input()?><input type="hidden" name="action" value="shipment_event"><input type="hidden" name="id" value="<?=$s['id']?>"><div class="row g-2"><div class="col-12"><?php select_field('Update tugas','event_type',array_filter(['accepted'=>'Terima tugas','pickup_requested'=>'Ajukan pickup untuk ACC','location'=>'Perbarui lokasi','delivered'=>'Barang sampai'],fn($k)=>$k===$next||($k==='location'&&in_array($s['status'],['accepted','picked_up'],true)),ARRAY_FILTER_USE_KEY));?></div><div class="col-12"><label class="form-label">Keterangan / kondisi barang</label><textarea class="form-control" name="note" rows="2" required placeholder="Misalnya jumlah koli, kondisi segel, penerima"></textarea></div><div class="col-md-6"><label class="form-label">Latitude</label><input class="form-control" id="lat<?=$s['id']?>" type="number" step="any" name="latitude"></div><div class="col-md-6"><label class="form-label">Longitude</label><input class="form-control" id="lng<?=$s['id']?>" type="number" step="any" name="longitude"></div><div class="col-12"><button type="button" class="btn btn-outline-secondary btn-sm" onclick="getGPS(<?=$s['id']?>)">📍 Gunakan GPS perangkat</button></div><div class="col-12"><label class="form-label">Bukti foto / PDF <span class="helper">(wajib saat delivered, max. 5 MB)</span></label><input class="form-control" type="file" name="proof" accept=".jpg,.jpeg,.png,.webp,.pdf"></div><div class="col-12"><button class="btn btn-coco w-100">Kirim pembaruan</button></div></div></form><?php endif;?>
<?php if(($manager||$u['role']==='coop')&&$s['status']==='pickup_pending'):?><div class="p-3 mb-3" style="background:#f4f9e7;border-radius:12px"><strong>Verifikasi pengambilan barang</strong><p class="helper mt-1">Periksa kondisi dan jumlah barang yang diserahkan driver sebelum menyetujui pickup.</p><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="approve_pickup"><input type="hidden" name="id" value="<?=$s['id']?>"><label class="form-label">Catatan serah terima / alasan penolakan</label><textarea name="note" class="form-control mb-2" rows="2" required></textarea><button name="decision" value="approved" class="btn btn-coco btn-sm me-2">ACC pickup</button><button name="decision" value="rejected" class="btn btn-outline-danger btn-sm">Tolak pickup</button></form></div><?php endif;?>
<div class="helper fw-bold mb-2">TIMELINE STATUS</div><div style="max-height:290px;overflow:auto"><?php foreach($by[$s['id']]??[] as $ev):?><div class="pb-2 mb-2 border-bottom"><div class="d-flex justify-content-between"><strong><?=e(status_text($ev['event_type']))?></strong><span class="helper"><?=e($ev['created_at'])?></span></div><p class="helper mb-1"><?=e($ev['actor_name'])?>: <?=e($ev['note'])?></p><?php if($ev['latitude']!==null):?><a target="_blank" class="small" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?=e($ev['latitude'])?>&mlon=<?=e($ev['longitude'])?>#map=15/<?=e($ev['latitude'])?>/<?=e($ev['longitude'])?>">📍 Buka koordinat lokasi</a><?php endif;?><?php if($ev['proof_path']):?><a class="small ms-2" href="<?=e(app_base().'/download.php?id='.$ev['id'])?>" target="_blank">Bukti kirim ↗</a><?php endif;?></div><?php endforeach;?></div></div></div><?php endforeach;?></div><?php if(!$ships):?><div class="panel"><?php table_empty('Belum ada pengiriman yang ditugaskan.');?></div><?php endif;?><script>function getGPS(id){if(!navigator.geolocation)return alert('GPS tidak tersedia');navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat'+id).value=p.coords.latitude.toFixed(7);document.getElementById('lng'+id).value=p.coords.longitude.toFixed(7)},()=>alert('Izin lokasi gagal / ditolak'))}</script>
<?php }
